      "join.eyebrow": "✦ REJOIGNEZ DEGAJA ✦", "join.title": "Vous faites des lectures, ou vous nous recommandez ?", "join.desc": "Devenez conseillère indépendante chez DEGAJA, ou gagnez 40 % de commission en tant que partenaire en nous recommandant.", "join.advisorBtn": "Devenir conseillère →", "join.partnerBtn": "Devenir partenaire →",
