      "chat.links": "Cartas · Estrellas · Números", "chat.human": "Asesoría", "chat.account": "Mi DEGAJA",
      "join.eyebrow": "✦ ÚNETE A DEGAJA ✦", "join.title": "¿Haces lecturas tú misma, o nos recomiendas?", "join.desc": "Conviértete en asesora independiente en DEGAJA, o gana un 40 % de comisión como socio/a recomendándonos.", "join.advisorBtn": "Sé asesora →", "join.partnerBtn": "Sé socio/a →",
