      "footer.impressum": "Юридическая информация", "footer.datenschutz": "Конфиденциальность", "footer.agb": "Условия", "footer.widerruf": "Отказ от договора", "footer.kontakt": "Контакты", "footer.faq": "FAQ", "footer.werdeberaterin": "Стать консультанткой", "footer.werdepartner": "Стать партнёром",
